package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.articles.JdbcEvidenceValidity;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.service.articles.EvidenceValidityService;
import com.lianxibu.site.service.content.*;
import com.lianxibu.site.service.jobs.VersionValidityService.*;
import java.util.*;
import org.junit.jupiter.api.*;
import tools.jackson.databind.JsonNode;

class VersionValidityLedgerServiceTest {
    ResultJdbcStoreTest fixture;VersionValidityLedgerService ledger;ContentReviewWriteService writer;ContentReadService contents;FrozenContentVersionService versions;
    @BeforeEach void setup(){fixture=new ResultJdbcStoreTest();fixture.fixture();install();}
    void install(){
        fixture.apply();fixture.jdbc.execute("ALTER TABLE article_revisions ADD validity_revision BIGINT NOT NULL DEFAULT 0");fixture.jdbc.execute("ALTER TABLE article_revisions ADD article_id VARCHAR(64)");fixture.jdbc.update("UPDATE article_revisions SET article_id='fictional-article'");
        fixture.jdbc.execute("DROP TABLE IF EXISTS articles");fixture.jdbc.execute("DROP TABLE IF EXISTS source_run_items");fixture.jdbc.execute("CREATE TABLE articles(id VARCHAR(64) PRIMARY KEY)");fixture.jdbc.update("INSERT INTO articles VALUES('fictional-article')");fixture.jdbc.execute("CREATE TABLE source_run_items(id VARCHAR(64) PRIMARY KEY,category VARCHAR(16),validity_revision BIGINT NOT NULL DEFAULT 0,effective_valid BOOLEAN NOT NULL DEFAULT TRUE)");fixture.jdbc.update("INSERT INTO source_run_items(id,category) VALUES('fictional-citation','model')");
        for(String column:new String[]{"validity_revision BIGINT","reverses_disposition_id VARCHAR(64)"})fixture.jdbc.execute("ALTER TABLE jobs ADD "+column);
        versions=new FrozenContentVersionService(new JdbcFrozenContentVersions(fixture.source));contents=new ContentReadService(new JdbcContentReads(fixture.source),fixture.tx,ContentReadService.denyUnverifiedReferences());writer=new ContentReviewWriteService(new JdbcReviewPublication(fixture.source),new GeneratedContentService(new JdbcGeneratedContents(fixture.source),fixture.clock),fixture.clock);restart();
    }
    void restart(){ledger=new VersionValidityLedgerService(new JdbcVersionValidity(fixture.source),versions,new EvidenceValidityService(new JdbcEvidenceValidity(fixture.source)),writer,fixture.clock,"fictional-owner");}
    Command command(JsonNode target,long expected,Action action,String reverse){return new Command(target,expected,action,"Fictional reviewed evidence",reverse);}
    String append(Command command,String key){String hash=VersionValidityService.commandHash(command,VersionValidityService.canonicalTarget(command.target()));return fixture.writes.execute(fixture.action(key),k->{var old=ledger.committed(k,hash);return old==null?null:old.dispositionId();},a->{ledger.lockStableIdentity(command.target());return ledger.append(command,hash,command.expectedValidityRevision()+1,key);});}
    JsonNode article(){return CanonicalJson.parse("{\"kind\":\"article_revision\",\"id\":\"fictional-citation\"}");}
    JsonNode content(){var row=contents.reviewSnapshot("report","fictional-report").orElseThrow();return CanonicalJson.parse(JdbcFrozenContentVersions.version(new ContentVersionKey(row.kind(),row.id(),row.bodyRevision(),HexFormat.of().formatHex(row.bodyHashV1()),row.inputJobId())));}
    @Test void cumulativePermanentInvalidationsReverseIndividuallyAndReplaysKeepOriginalResult(){var target=article();String first=append(command(target,0,Action.INVALIDATE,null),"fictional-invalid-1"),second=append(command(target,1,Action.INVALIDATE,null),"fictional-invalid-2");assertEquals(new Validity(2,false,Set.of(first,second)),ledger.validity(target));append(command(target,2,Action.REVERSE_INVALIDATION,first),"fictional-reverse-1");assertEquals(new Validity(3,false,Set.of(second)),ledger.validity(target));append(command(target,3,Action.REVERSE_INVALIDATION,second),"fictional-reverse-2");restart();assertEquals(new Validity(4,true,Set.of()),ledger.validity(target));String hash=VersionValidityService.commandHash(command(target,0,Action.INVALIDATE,null),VersionValidityService.canonicalTarget(target));var old=ledger.committed("fictional-invalid-1",hash);assertEquals(1,old.validityRevision());assertFalse(old.effectiveValid());assertEquals(first,append(command(target,0,Action.INVALIDATE,null),"fictional-invalid-1"));assertThrows(Rejected.class,()->append(command(target,4,Action.REVERSE_INVALIDATION,first),"fictional-reverse-again"));}
    @Test void contentHistoryAndCatalogAreDifferentExactIdentities(){var old=content();String id=append(command(old,0,Action.INVALIDATE,null),"fictional-content-invalid");assertFalse(ledger.validity(old).effectiveValid());assertTrue(ledger.validity(article()).effectiveValid());var catalog=CanonicalJson.parse("{\"kind\":\"catalog_evidence\",\"item_id\":\"fictional-citation\"}");append(command(catalog,0,Action.INVALIDATE,null),"fictional-catalog-invalid");assertEquals(Set.of(id),ledger.validity(old).activeDispositionIds());fixture.jdbc.update("UPDATE contents SET body_revision=2,body_json=?,body_hash_v1=?",ResultJdbcStoreTest.BODY.replace("Fictional text","Fictional replacement"),new byte[32]);assertEquals(1,ledger.validity(old).revision());var wrong=old.deepCopy();((tools.jackson.databind.node.ObjectNode)wrong).put("content_kind","agent");assertFalse(ledger.exactVersionExists(wrong));}
    @Test void missingLedgerProjectionTamperingAndChangedCommandsCannotGuessValidity(){var target=article();append(command(target,0,Action.INVALIDATE,null),"fictional-shared");assertThrows(Rejected.class,()->append(new Command(target,0,Action.INVALIDATE,"Fictional different reason",null),"fictional-shared"));var missing=CanonicalJson.parse("{\"kind\":\"article_revision\",\"id\":\"fictional-missing\"}");assertThrows(Rejected.class,()->ledger.validity(missing));fixture.jdbc.update("DELETE FROM jobs WHERE target_type='article_revision'");assertThrows(IllegalStateException.class,()->ledger.validity(target));}
    @Test void payloadOrPhysicalProjectionMismatchFailClosed(){var target=article();append(command(target,0,Action.INVALIDATE,null),"fictional-invalid");fixture.jdbc.update("UPDATE article_revisions SET validity_revision=0");assertThrows(IllegalStateException.class,()->ledger.validity(target));fixture.jdbc.update("UPDATE article_revisions SET validity_revision=1");fixture.jdbc.update("UPDATE jobs SET action_payload=? WHERE target_type='article_revision'","{\"schema_version\":\"content-validity-v1\",\"action\":\"invalidate_conclusion\",\"validity_revision\":2,\"invalidation_id\":null}");assertThrows(IllegalStateException.class,()->ledger.validity(target));}
    @Test void ledgerAndPhysicalProjectionRollbackTogetherAndAckLossFindsPermanentReceipt(){var target=article();assertThrows(RuntimeException.class,()->fixture.writes.execute(fixture.action("fictional-rollback"),k->null,a->{var command=command(target,0,Action.INVALIDATE,null);ledger.lockStableIdentity(target);ledger.append(command,VersionValidityService.commandHash(command,VersionValidityService.canonicalTarget(target)),1,"fictional-rollback");throw new IllegalStateException("fictional queue failed");}));assertEquals(new Validity(0,true,Set.of()),ledger.validity(target));fixture.tx.ackLost=true;String id=append(command(target,0,Action.INVALIDATE,null),"fictional-ack-lost");restart();assertEquals(id,append(command(target,0,Action.INVALIDATE,null),"fictional-ack-lost"));assertEquals(1,ledger.validity(target).revision());}
}
